   "q": "Judge these statements about explanations of the photo-taking-impairment effect.<br>I. The offloading hypothesis predicts that a photo you cannot keep impairs memory as much as a photo you can keep.<br>II. The attentional-disengagement hypothesis predicts an impairment whether or not the photo is kept.",
