   "a": 1,
   "spot": "A control condition: what alternative explanation does it exclude?",
   "why": "If both kinds of interference removed the advantage, it could simply be that <b>any</b> busy mind loses it. Because the advantage disappeared under <b>verbal</b> but not <b>spatial</b> interference, the effect depends on <b>language</b> specifically. The spatial task is the <b>control</b>."
